import random
from collections import deque

def random_graph(n, d, seed=0):
    """ogni nodo apre d connessioni uscenti verso nodi scelti a caso (come Bitcoin, 8 outbound)"""
    rnd = random.Random(seed)
    adj = [set() for _ in range(n)]
    for v in range(n):
        out = set()                        # connessioni uscenti aperte da v
        while len(out) < d:
            w = rnd.randrange(n)
            if w != v and w not in adj[v]:
                out.add(w)
                adj[v].add(w); adj[w].add(v)   # le connessioni TCP sono bidirezionali
    return adj

def flood_rounds(adj, src):
    """numero di 'turni' di gossip (inv) perché tutti ricevano il messaggio"""
    dist = {src: 0}
    q = deque([src])
    while q:
        v = q.popleft()
        for w in adj[v]:
            if w not in dist:
                dist[w] = dist[v] + 1
                q.append(w)
    return max(dist.values()), len(dist)

for n in [1000, 10000, 20000]:
    adj = random_graph(n, 8)
    r, reached = flood_rounds(adj, 0)
    msgs = sum(len(a) for a in adj)    # ogni nodo annuncia a tutti i vicini: 2|E| messaggi inv
    print(f"n={n:6d} turni={r} raggiunti={reached} inv inviati={msgs} (grado medio {msgs/n:.1f})")
